<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Snippet\Domain\ValueObject\SnippetTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait SnippetTenantAccessor
{
    private ?SnippetTenantVO $_tenant = null;
    public function getTenant(): ?TenantRef
    {
        return $this->_tenant?->value();
    }
    public function tenant(): ?SnippetTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return null !== $this->_tenant && !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(SnippetTenantVO|TenantRef|null $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = SnippetTenantVO::from($tenant);
        return $copy;
    }
}
